#include <bits/stdc++.h>
using namespace std;

/*
CONSTRUCTION:

Odd N: print numbers 1..N^2 in row-major order.
  Row i (0-indexed) holds iN+1..iN+N, mean = iN + (N+1)/2,
  which is the middle element of the row (N odd).
  Column j holds j+1, N+j+1, ..., mean = N(N-1)/2 + j + 1,
  which is the element in the middle row (i = (N-1)/2).

Even N >= 4: use base value A (all row means share structure):
  Row for base b:  b, b+1, ..., b+(N-2), b+c   with c = (3N-2)/2.
  Row sum  = N*b + (N-1)(N-2)/2 + c = N*(b + N/2)  -> mean = b + N/2, present (t = N/2 <= N-2).
  So every column j (0..N-2) has mean avg(b's) + j and the last column mean avg(b's) + c.
  If the bases b_i = A + d_i have average A and A is itself one of the bases
  (sum of deviations = 0, one deviation is 0), then every column mean is an
  element present in that column (in the row with deviation 0).
  Choose deviations as multiples of L = 3N/2:
      {0, L, 3L, -4L} ∪ {+(5+2j)L, -(5+2j)L}, j = 1..(N-4)/2
  Total count: 1 + 3 + (N-4) = N, sum = L(1+3-4) = 0.
  All pairwise differences are nonzero multiples of L = 3N/2 > c = (3N-2)/2,
  while possible value collisions require a difference in
  [-c, c] = [-(3N-2)/2, (3N-2)/2]  -> impossible. Hence all N^2 entries distinct.
  Bases are chosen so the minimum entry is 1 and the maximum stays far below 10^6.

N = 2: impossible (mean of two distinct numbers cannot equal either), print -1.
*/

int main(){
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);
    long long N;
    if(!(cin >> N)) return 0;

    if(N == 2){
        cout << -1 << "\n";
        return 0;
    }

    if(N % 2 == 1){
        for(long long i = 0; i < N; i++){
            for(long long j = 0; j < N; j++){
                cout << (i*N + j + 1);
                cout << ((j + 1 == N) ? '\n' : ' ');
            }
        }
        return 0;
    }

    // even N >= 4
    long long L = 3*N/2;            // 3N/2
    long long c = (3*N - 2)/2;      // (3N-2)/2
    long long A = (N + 1)*L + 1;    // average of the bases, itself used as a base

    vector<long long> devs;
    devs.reserve((size_t)N);
    devs.push_back(0);
    devs.push_back(L);
    devs.push_back(3*L);
    devs.push_back(-4*L);
    for(long long j = 1; j <= (N - 4)/2; j++){
        devs.push_back((5 + 2*j)*L);
        devs.push_back(-(5 + 2*j)*L);
    }

    for(long long d : devs){
        long long base = A + d;
        for(long long t = 0; t <= N - 2; t++){
            cout << (base + t) << ' ';
        }
        cout << (base + c) << "\n";
    }
    return 0;
}
